// Shown as one file so it compiles standalone; in a real build the three
// sections live in prices.h, prices.cpp and main.cpp respectively.

// --- prices.h : the interface -------------------------------------------
#ifndef PRICES_H
#define PRICES_H

double grossPnl(double entryPrice, double exitPrice, int shares);  // declaration

#endif

// --- prices.cpp : the implementation ------------------------------------
double grossPnl(double entryPrice, double exitPrice, int shares) {  // definition
    return (exitPrice - entryPrice) * shares;
}

// --- main.cpp : the user -------------------------------------------------
#include <iostream>

int main() {
    std::cout << "PnL: " << grossPnl(42.17, 43.05, 250) << '\n';
    return 0;
}

